package br.com.onda;
import android.app.*;import android.content.*;import android.content.pm.*;import android.graphics.Bitmap;import android.widget.*;import org.junit.*;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.security.*;import java.util.*;
@androidx.media3.common.util.UnstableApi
public class SigningMigrationTest {
 private final android.app.Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();
 @Test @SuppressWarnings("deprecation") public void independentInstallationAndPinnedNewCertificate()throws Exception{assertEquals("br.com.onda.player",c.getPackageName());PackageInfo current=c.getPackageManager().getPackageInfo(c.getPackageName(),PackageManager.GET_SIGNATURES),legacy=c.getPackageManager().getPackageInfo("br.com.onda.musica",PackageManager.GET_SIGNATURES);assertEquals(105,current.versionCode);assertEquals(104,legacy.versionCode);byte[] digest=MessageDigest.getInstance("SHA-256").digest(current.signatures[0].toByteArray());StringBuilder hash=new StringBuilder();for(byte b:digest)hash.append(String.format(Locale.ROOT,"%02x",b&255));assertEquals("617512f0559a81aa408a690f0df9a758ed94633c86e4a81ca7bca144b88d5801",hash.toString());assertFalse(Arrays.equals(current.signatures[0].toByteArray(),legacy.signatures[0].toByteArray()));assertEquals("Onda Novo",c.getApplicationInfo().loadLabel(c.getPackageManager()).toString());}
 @Test public void previousSourceBackupImportsAndRepeatedImportDoesNotDuplicate()throws Exception{String raw=new String(Files.readAllBytes(new File(c.getFilesDir(),"legacy-backup.json").toPath()),StandardCharsets.UTF_8);BackupData.Archive archive=BackupData.parse(raw);assertEquals(1,archive.favorites.size());c.getSharedPreferences("migration-new",0).edit().putString("marker","new-preserved").commit();BackupData.Plan plan=BackupStore.plan(c,archive,BackupStore.tracks(c));assertEquals(1,plan.matched);assertEquals(0,plan.missing);assertEquals(0,plan.ambiguous);BackupStore.apply(c,plan);assertEquals(1,c.getSharedPreferences("library",0).getStringSet("favorites",Collections.emptySet()).size());assertEquals("Transferência teste",PlaylistStore.read(c).get(0).name);assertEquals(VoiceCommand.Action.PAUSE,VoicePhrases.read(c).find("pausa da transferência").action);BackupData.Plan again=BackupStore.plan(c,archive,BackupStore.tracks(c));assertEquals(0,again.addedFavorites+again.addedLists+again.addedSongs+again.addedPhrases);assertEquals("new-preserved",c.getSharedPreferences("migration-new",0).getString("marker",""));}
 @Test public void updaterAcceptsFutureSameKeyButRejectsLegacyPackage()throws Exception{UpdateRepository.verify(c,new File(c.getFilesDir(),"future-update.apk"),106);try{UpdateRepository.verify(c,new File(c.getFilesDir(),"legacy.apk"),104);fail("Legacy package must not be installed as an update");}catch(IOException expected){}BackupActivity activity=(BackupActivity)ins.startActivitySync(new Intent(c,BackupActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ins.waitForIdleSync();ins.runOnMainSync(()->{android.view.View root=activity.findViewById(android.R.id.content);expand(root);});ins.waitForIdleSync();Bitmap bitmap=ins.getUiAutomation().takeScreenshot();try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"signing-transfer.png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}finally{bitmap.recycle();ins.runOnMainSync(activity::finish);}}
 private static void expand(android.view.View view){if(view instanceof Ui.Section)((Ui.Section)view).setExpanded(true);if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)expand(group.getChildAt(i));}}
}
